export function translateAppCopy(locale: Locale, key: string, values?: Record<string, string | number>): string {
  const template = translations[locale]?.[key] ?? additionalTranslations[locale]?.[key] ?? workflowTranslations[locale]?.[key] ?? featureTranslations[locale]?.[key] ?? stemTranslations[locale]?.[key] ?? practiceTranslations[locale]?.[key] ?? guidedPracticeTranslations[locale]?.[key] ?? trainerTranslations[locale]?.[key] ?? trainerEntryTranslations[locale]?.[key] ?? integratedPracticeTranslations[locale]?.[key] ?? key;
  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(values?.[name] ?? `{${name}}`));
}
